import{_ as i,r as o,o as r,c as n,a as t,b as l,d as s,e as d}from"./app.ChrdILIc.js";import"./chunks/three-vendor.DK3fmyXa.js";const k=JSON.parse('{"title":"Development Modes","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/type.md","filePath":"en/development/type.md","lastUpdated":1778395361000}'),c={name:"en/development/type.md"};function h(u,e,m,p,g,f){const a=o("ArticleMetadata");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"development-modes",tabindex:"-1"},[l("Development Modes "),t("a",{class:"header-anchor",href:"#development-modes","aria-label":'Permalink to "Development Modes"'},"​")],-1)),s(a),e[1]||(e[1]=d('<p><code>/en/development/type</code> explains how to choose the right delivery mode for a project stage, and what quality baseline still applies in every case.</p><h2 id="when-to-use-each-mode" tabindex="-1">When to use each mode <a class="header-anchor" href="#when-to-use-each-mode" aria-label="Permalink to &quot;When to use each mode&quot;">​</a></h2><p>Teams usually work in two modes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Mode</th><th style="text-align:left;">Best for</th><th style="text-align:left;">Primary goal</th><th style="text-align:left;">Typical cadence</th></tr></thead><tbody><tr><td style="text-align:left;">Standard delivery</td><td style="text-align:left;">Clear requirements, wider impact, stable release expectations</td><td style="text-align:left;">Reduce risk and keep delivery traceable</td><td style="text-align:left;">Milestone or release based</td></tr><tr><td style="text-align:left;">Rapid iteration</td><td style="text-align:left;">Unclear requirements, experiments, MVP validation</td><td style="text-align:left;">Learn fast and shorten feedback loops</td><td style="text-align:left;">Daily or weekly</td></tr></tbody></table><p>Do not choose based on speed alone. Evaluate:</p><ul><li><strong>Requirement stability</strong>: how likely the scope is to change.</li><li><strong>Business risk</strong>: whether the work touches payments, permissions, security, or critical paths.</li><li><strong>Coordination cost</strong>: how many roles and dependencies must stay aligned.</li></ul><h2 id="shared-principles" tabindex="-1">Shared principles <a class="header-anchor" href="#shared-principles" aria-label="Permalink to &quot;Shared principles&quot;">​</a></h2><p>Both modes should follow the same fundamentals:</p><ul><li><strong>Align on goals before coding</strong>.</li><li><strong>Ship in small slices and validate continuously</strong>.</li><li><strong>Keep documentation in sync with code and decisions</strong>.</li><li><strong>Raise blockers early instead of hiding schedule risk</strong>.</li><li><strong>Never drop the minimum quality bar</strong>.</li></ul><h2 id="docker-first-development" tabindex="-1">Docker-first development <a class="header-anchor" href="#docker-first-development" aria-label="Permalink to &quot;Docker-first development&quot;">​</a></h2><p>For modern team delivery, a <strong>docker-first</strong> approach is recommended: put as much of the project runtime, service dependencies, and integration chain into Docker as practical, without forcing every personal tool into containers.</p><h3 id="recommended-mindset" tabindex="-1">Recommended mindset <a class="header-anchor" href="#recommended-mindset" aria-label="Permalink to &quot;Recommended mindset&quot;">​</a></h3><ul><li><strong>Aim for almost all-in Docker, but not docker-only</strong>.</li><li><strong>Prioritize team-wide consistency over personal machine differences</strong>.</li><li><strong>Use Docker to reduce friction</strong>, not to create ceremony.</li></ul><h3 id="good-candidates-for-docker" tabindex="-1">Good candidates for Docker <a class="header-anchor" href="#good-candidates-for-docker" aria-label="Permalink to &quot;Good candidates for Docker&quot;">​</a></h3><ul><li>frontend, backend, BFF, and gateway services,</li><li>databases and caches such as MySQL, PostgreSQL, Redis, or MongoDB,</li><li>queues, object storage, and local mock services,</li><li>test dependencies and integration environments,</li><li>language runtimes and build environments such as Node, Java, Python, or Go.</li></ul><h3 id="things-that-do-not-need-to-be-containerized" tabindex="-1">Things that do not need to be containerized <a class="header-anchor" href="#things-that-do-not-need-to-be-containerized" aria-label="Permalink to &quot;Things that do not need to be containerized&quot;">​</a></h3><ul><li>the IDE itself,</li><li>browsers,</li><li>system-level proxy, input, or clipboard tools,</li><li>design tools and collaboration apps,</li><li>tools that depend heavily on local GUI or hardware access.</li></ul><h3 id="why-it-helps" tabindex="-1">Why it helps <a class="header-anchor" href="#why-it-helps" aria-label="Permalink to &quot;Why it helps&quot;">​</a></h3><ul><li><strong>Consistent environments</strong> across the team.</li><li><strong>Faster onboarding</strong> for new contributors.</li><li><strong>More stable integration</strong> across service dependencies.</li><li><strong>Closer parity with deployment environments</strong>.</li><li><strong>Better automation</strong> across local development, testing, and CI.</li></ul><h3 id="tradeoffs" tabindex="-1">Tradeoffs <a class="header-anchor" href="#tradeoffs" aria-label="Permalink to &quot;Tradeoffs&quot;">​</a></h3><ul><li>file mounts and hot reload can be slower on some machines,</li><li>debugging can become more complex,</li><li>too many containers can create maintenance overhead.</li></ul><p>A practical target is:</p><ul><li>keep <code>IDE + browser + Docker + Git</code> on the host,</li><li>containerize project runtime dependencies,</li><li>use <code>docker compose</code> to bring up the local stack,</li><li>use scripts or <code>devcontainer</code> support to reduce setup cost.</li></ul><h3 id="best-fit-scenarios" tabindex="-1">Best-fit scenarios <a class="header-anchor" href="#best-fit-scenarios" aria-label="Permalink to &quot;Best-fit scenarios&quot;">​</a></h3><p>Docker-first works especially well when:</p><ul><li>team members often hit environment drift,</li><li>local setup is heavy or fragile,</li><li>multiple services must be integrated together,</li><li>development, testing, and CI should stay as close as possible.</li></ul><h3 id="summary-recommendation" tabindex="-1">Summary recommendation <a class="header-anchor" href="#summary-recommendation" aria-label="Permalink to &quot;Summary recommendation&quot;">​</a></h3><p>If the question is “can we go all in Docker?”, the better answer is: <strong>the project environment can be almost entirely Docker-based, but the team should stay docker-first rather than docker-only.</strong></p><h2 id="standard-delivery" tabindex="-1">Standard delivery <a class="header-anchor" href="#standard-delivery" aria-label="Permalink to &quot;Standard delivery&quot;">​</a></h2><p>Use the standard flow for formal projects, cross-team collaboration, and anything that requires predictable quality.</p><h3 id="_1-clarify-requirements" tabindex="-1">1. Clarify requirements <a class="header-anchor" href="#_1-clarify-requirements" aria-label="Permalink to &quot;1. Clarify requirements&quot;">​</a></h3><ul><li>Define business goals, user scenarios, edge cases, and priorities.</li><li>Confirm PRD, prototypes, acceptance criteria, and external dependencies.</li><li>Identify release windows, approvals, and data or infrastructure constraints.</li></ul><p><strong>Expected outputs</strong></p><ul><li>Requirement notes or PRD</li><li>Acceptance criteria</li><li>Risk and dependency list</li></ul><h3 id="_2-design-the-solution" tabindex="-1">2. Design the solution <a class="header-anchor" href="#_2-design-the-solution" aria-label="Permalink to &quot;2. Design the solution&quot;">​</a></h3><ul><li>Confirm architecture, module boundaries, data structures, API contracts, and failure handling.</li><li>Review performance, security, observability, and rollback strategy.</li><li>Break work into tasks and estimate effort.</li></ul><p><strong>Expected outputs</strong></p><ul><li>Technical design</li><li>API definition</li><li>Timeline and owners</li></ul><h3 id="_3-prepare-execution" tabindex="-1">3. Prepare execution <a class="header-anchor" href="#_3-prepare-execution" aria-label="Permalink to &quot;3. Prepare execution&quot;">​</a></h3><ul><li>Align UI/UX details with design, product, and engineering.</li><li>Set up branches, environments, test data, and configuration.</li><li>Include logging, monitoring, permissions, and analytics requirements.</li></ul><h3 id="_4-implement" tabindex="-1">4. Implement <a class="header-anchor" href="#_4-implement" aria-label="Permalink to &quot;4. Implement&quot;">​</a></h3><ul><li>Split work by module to reduce conflicts.</li><li>Build core flows first, then cover secondary states and edge cases.</li><li>Add tests or at least repeatable verification for critical logic.</li></ul><h3 id="_5-integrate-and-test" tabindex="-1">5. Integrate and test <a class="header-anchor" href="#_5-integrate-and-test" aria-label="Permalink to &quot;5. Integrate and test&quot;">​</a></h3><ul><li>Validate API fields, empty states, error paths, and permission checks.</li><li>Run functional, regression, and key-path verification.</li><li>Add staged rollout or rehearsal steps for higher-risk modules.</li></ul><h3 id="_6-review-and-release" tabindex="-1">6. Review and release <a class="header-anchor" href="#_6-review-and-release" aria-label="Permalink to &quot;6. Review and release&quot;">​</a></h3><ul><li>Use Pull Requests for code review.</li><li>Confirm change notes, rollback plan, and release checklist.</li><li>After release, watch logs, alerts, and business metrics.</li></ul><h3 id="_7-retrospective" tabindex="-1">7. Retrospective <a class="header-anchor" href="#_7-retrospective" aria-label="Permalink to &quot;7. Retrospective&quot;">​</a></h3><ul><li>Capture requirement drift, testing gaps, release issues, and follow-up actions.</li><li>Turn good patterns into reusable templates or standards.</li></ul><h2 id="rapid-iteration" tabindex="-1">Rapid iteration <a class="header-anchor" href="#rapid-iteration" aria-label="Permalink to &quot;Rapid iteration&quot;">​</a></h2><p>Rapid iteration does not mean “skip process”. It means “shorten the feedback loop”. It works well for prototypes, MVPs, internal tools, campaign pages, and product discovery.</p><h3 id="suggested-loop" tabindex="-1">Suggested loop <a class="header-anchor" href="#suggested-loop" aria-label="Permalink to &quot;Suggested loop&quot;">​</a></h3><ol><li><strong>Pick the smallest validation target</strong> for this round.</li><li><strong>Shrink the scope</strong> and state what is intentionally out.</li><li><strong>Use lightweight design artifacts</strong> such as sketches, short notes, or API agreements.</li><li><strong>Work in parallel</strong> while aligning contracts early.</li><li><strong>Sync daily</strong> on progress, blockers, and requirement changes.</li><li><strong>Keep something runnable every day</strong>.</li><li><strong>Collect feedback early</strong> from stakeholders or real users.</li><li><strong>Iterate from evidence</strong>, not assumptions.</li></ol><h3 id="good-fit-when" tabindex="-1">Good fit when <a class="header-anchor" href="#good-fit-when" aria-label="Permalink to &quot;Good fit when&quot;">​</a></h3><ul><li>The business can tolerate trial and error.</li><li>The module is not directly part of a critical transaction or security flow.</li><li>Decision makers are available to unblock and reprioritize quickly.</li></ul><h3 id="common-risks" tabindex="-1">Common risks <a class="header-anchor" href="#common-risks" aria-label="Permalink to &quot;Common risks&quot;">​</a></h3><ul><li>No clear “out of scope” boundary.</li><li>Weak API alignment that creates rework later.</li><li>Demo code quietly becoming production code without hardening.</li></ul><h2 id="switching-modes" tabindex="-1">Switching modes <a class="header-anchor" href="#switching-modes" aria-label="Permalink to &quot;Switching modes&quot;">​</a></h2><p>Most projects should move between the two modes:</p><ul><li>Start with rapid iteration during discovery.</li><li>Move to standard delivery once the solution is stable.</li><li>Use mixed pacing when core flows need stronger control than surrounding pages.</li></ul><p>Switch back to standard delivery when:</p><ul><li>requirements stop changing frequently,</li><li>the feature enters long-term maintenance,</li><li>or the scope starts touching security, permissions, payments, or compliance.</li></ul><h2 id="minimum-quality-baseline" tabindex="-1">Minimum quality baseline <a class="header-anchor" href="#minimum-quality-baseline" aria-label="Permalink to &quot;Minimum quality baseline&quot;">​</a></h2><p>No matter the mode:</p><ul><li>Run self-checks before submitting code.</li><li>Keep naming, structure, and readability consistent.</li><li>Verify key pages, APIs, and failure paths.</li><li>Merge through Pull Requests instead of pushing to protected branches.</li><li>Define rollback steps, owners, and release watch metrics.</li></ul><h2 id="recommended-artifacts" tabindex="-1">Recommended artifacts <a class="header-anchor" href="#recommended-artifacts" aria-label="Permalink to &quot;Recommended artifacts&quot;">​</a></h2><p>Keep at least these records:</p><ul><li>requirement summary or meeting outcome,</li><li>technical note or lightweight design,</li><li>task breakdown and owners,</li><li>test or acceptance record,</li><li>release notes and rollback plan.</li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Standard delivery answers “how do we ship reliably”. Rapid iteration answers “how do we learn faster”. Mature teams know when to use each one and when to switch.</p>',69))])}const w=i(c,[["render",h]]);export{k as __pageData,w as default};
